import articles from '../data/articles';

export const newsService = {
  fetchNews: async ({ category = 'All', page = 1, pageSize = 25 }) => {
    // filter articles by category if not 'All'
    let filtered = articles;
    if (category && category !== 'All') {
      filtered = articles.filter((a) => a.category.toLowerCase() === category.toLowerCase());
    }
    // paging - slice without wrapping so each article appears once
    const start = (page - 1) * pageSize;
    const results = filtered.slice(start, start + pageSize);
    return { results, total: filtered.length }; // include total for client logic
  },
  getArticleById: async (id) => {
    return articles.find((a) => a.id === Number(id));
  }
};
